record.field:
picking = env['stock.picking'].browse(record.res_id).exists()
if picking and picking.picking_type_id.code == 'incoming':
    env.ref(
        'fmcg_business_automation.action_create_incoming_lot_serial'
    ).with_context(
        active_model='stock.picking',
        active_id=picking.id,
        active_ids=[picking.id],
        old_values=None,
        domain_post=None,
    ).run()
else:
    raise UserError(
        'Nghiệp vụ xử lý thiếu Lot/Serial chưa được triển khai.'
    )
